export const translateTask = (
  locale: DashboardLocale,
  key: TaskTextKey,
  variables?: DashboardMessageVariables,
): string => translateDashboardMessage(taskMessages, locale, key, variables);

export const translateTaskPlural = (
  locale: DashboardLocale,
  key: TaskPluralKey,
  count: number,
  variables?: DashboardMessageVariables,
): string => translateDashboardPlural(taskMessages, locale, key, count, {
  count: new Intl.NumberFormat(locale).format(count),
  ...variables,
});
